# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MEZOPOTAMYA, MISIR, ANADOLU VE İRAN\'DA YÖNETİM ANLAYIŞI (TAR.9.2.2)</text>\n  <rect x="20" y="45" width="320" height="92" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">MEZOPOTAMYA (SÜMER, AKAD, BABİL, ASUR)</text>\n  <text x="32" y="88" font-size="10.5" fill="#78350f">• Sümer: Site şehir devletleri; Ensi / Patesi (Rahip-Kral)</text>\n  <text x="32" y="106" font-size="10.5" fill="#78350f">• Akad: İlk merkezi imparatorluk · Babil: Hammurabi</text>\n  <text x="32" y="124" font-size="10.5" font-weight="bold" fill="#b45309">• Kral tanrı değil, tanrının yeryüzündeki vekilidir</text>\n\n  <rect x="360" y="45" width="320" height="92" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">MISIR MEDENİYETİ (NOM → FİRAVUN)</text>\n  <text x="372" y="88" font-size="10.5" fill="#7f1d1d">• Nom şehir devletlerinden merkezi krallığa geçiş</text>\n  <text x="372" y="106" font-size="10.5" font-weight="bold" fill="#991b1b">• Firavun = Tanrı-Kral (Güneş tanrısı Ra/Horus\'un oğlu)</text>\n  <text x="372" y="124" font-size="10.5" fill="#7f1d1d">• Sorgulanamaz mutlak otorite; sözü kanun hükmündedir</text>\n\n  <rect x="20" y="147" width="320" height="90" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ANADOLU (HİTİT, URARTU, FRİG)</text>\n  <text x="32" y="190" font-size="10.5" fill="#1e3a8a">• Hitit: Büyük Kral (Labarna/Tabarna) + Kraliçe Tavananna</text>\n  <text x="32" y="208" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Pankuş Meclisi: Soylulardan oluşan danışma organı</text>\n  <text x="32" y="226" font-size="10.5" fill="#1e3a8a">• Kral başrahip, başkomutan ve başyargıçtır</text>\n\n  <rect x="360" y="147" width="320" height="90" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">İRAN (PERS İMPARATORLUĞU)</text>\n  <text x="372" y="190" font-size="10.5" font-weight="bold" fill="#14532d">• Satraplık: Ülkenin eyaletlere ayrılıp valilerle yönetimi</text>\n  <text x="372" y="208" font-size="10.5" fill="#14532d">• Şahgözü / Şahkulağı: Satrapları denetleyen müfettişler</text>\n  <text x="372" y="226" font-size="10.5" fill="#14532d">• Kral Yolu ve gelişmiş posta-haberleşme teşkilatı</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YUNAN, ROMA VE TÜRKİSTAN\'DA EGEMENLİK VE MECLİS YAPILARI</text>\n  <rect x="20" y="45" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">YUNAN &amp; İSKENDER</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• Polis şehir devletleri (Atina,</text>\n  <text x="32" y="110" font-size="10.5" fill="#1e3a8a">  Sparta, Korint)</text>\n  <text x="32" y="132" font-size="10.5" fill="#1e3a8a">• Krallık → Aristokrasi/Oligarşi</text>\n  <text x="32" y="150" font-size="10.5" fill="#1e3a8a">  → Tiranlık → Demokrasi</text>\n  <text x="32" y="172" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Atina: Ekklesia (Doğrudan</text>\n  <text x="32" y="190" font-size="10.5" font-weight="bold" fill="#1d4ed8">  Demokrasi) · Hellenizm</text>\n\n  <rect x="245" y="45" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7e22ce">ROMA MEDENİYETİ</text>\n  <text x="257" y="92" font-size="10.5" fill="#581c87">• 1) Krallık Dönemi</text>\n  <text x="257" y="114" font-size="10.5" font-weight="bold" fill="#7e22ce">• 2) Cumhuriyet Dönemi:</text>\n  <text x="257" y="132" font-size="10.5" fill="#581c87">  İki Konsül + Senato Meclisi</text>\n  <text x="257" y="152" font-size="10.5" fill="#581c87">• Patrici (soylu) - Pleb (halk)</text>\n  <text x="257" y="170" font-size="10.5" fill="#581c87">  ve 12 Levha Kanunları</text>\n  <text x="257" y="192" font-size="10.5" font-weight="bold" fill="#7e22ce">• 3) İmparatorluk Dönemi</text>\n\n  <rect x="470" y="45" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">TÜRKİSTAN (ASYA HUN)</text>\n  <text x="482" y="92" font-size="10.5" font-weight="bold" fill="#15803d">• Kut Anlayışı: Gök Tanrı\'nın</text>\n  <text x="482" y="110" font-size="10.5" fill="#14532d">  hükümdara yönetme yetkisi</text>\n  <text x="482" y="132" font-size="10.5" fill="#14532d">• Unvan: Şanyü / Tanhu / Kağan</text>\n  <text x="482" y="154" font-size="10.5" font-weight="bold" fill="#15803d">• Kurultay (Toy): Danışma meclisi</text>\n  <text x="482" y="174" font-size="10.5" fill="#14532d">• İkili Teşkilat (Doğu-Batı)</text>\n  <text x="482" y="194" font-size="10.5" fill="#14532d">• Töre: Yazısız hukuk kuralları</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ESKİ ÇAĞ\'DA ASKERÎ ORGANİZASYON VE ORDU SİSTEMLERİ</text>\n  <rect x="20" y="45" width="210" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">AKAD, ASUR, HİTİT, MISIR</text>\n  <text x="32" y="92" font-size="10.5" font-weight="bold" fill="#b45309">• Akad (Sargon): Tarihte bilinen</text>\n  <text x="32" y="110" font-size="10.5" font-weight="bold" fill="#b45309">  ilk düzenli ve daimî ordu</text>\n  <text x="32" y="134" font-size="10.5" fill="#78350f">• Asur: Süvari birlikleri, demir</text>\n  <text x="32" y="152" font-size="10.5" fill="#78350f">  silahlar ve kuşatma kuleleri</text>\n  <text x="32" y="176" font-size="10.5" fill="#78350f">• Hitit &amp; Mısır: Üç/iki kişilik</text>\n  <text x="32" y="194" font-size="10.5" fill="#78350f">  hızlı savaş arabaları</text>\n\n  <rect x="245" y="45" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">PERS, YUNAN VE ROMA</text>\n  <text x="257" y="92" font-size="10.5" fill="#1e3a8a">• Pers: Sayısı 10.000\'de sabit</text>\n  <text x="257" y="110" font-size="10.5" font-weight="bold" fill="#1d4ed8">  tutulan \'Ölümsüzler\' birliği</text>\n  <text x="257" y="134" font-size="10.5" fill="#1e3a8a">• Yunan / Makedon: Ağır zırhlı</text>\n  <text x="257" y="152" font-size="10.5" font-weight="bold" fill="#1d4ed8">  Hoplitler ve Falanks düzeni</text>\n  <text x="257" y="176" font-size="10.5" fill="#1e3a8a">• Roma: Profesyonel ve disiplinli</text>\n  <text x="257" y="194" font-size="10.5" font-weight="bold" fill="#1d4ed8">  Lejyon piyade teşkilatı</text>\n\n  <rect x="470" y="45" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">METE HAN &amp; ONLU SİSTEM</text>\n  <text x="482" y="92" font-size="10.5" font-weight="bold" fill="#15803d">• MÖ 209: Asya Hun Hükümdarı</text>\n  <text x="482" y="110" font-size="10.5" font-weight="bold" fill="#15803d">  Mete Han tarafından kuruldu</text>\n  <text x="482" y="134" font-size="10.5" fill="#14532d">• Onbaşı, Yüzbaşı, Binbaşı, Tümen</text>\n  <text x="482" y="154" font-size="10.5" fill="#14532d">• Ordu-Millet anlayışı (ücretsiz)</text>\n  <text x="482" y="174" font-size="10.5" fill="#14532d">• Atlı-okçu hafif süvariler, ıslıklı</text>\n  <text x="482" y="192" font-size="10.5" font-weight="bold" fill="#15803d">  ok ve Turan (Hilal) taktiği</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
